#!/usr/bin/env python3
"""Extract the reference CLI's embedded model catalog.

The catalog is one array of `{id, family, display_name, knowledge_cutoff,
capabilities, ...}` literals in the packed bundle. `capabilities` is what
decides the prompt a model receives: `lean_prompt` picks the lean `# Harness`
document over the classic `# System` one, and `opus_5_prompt_bundle` /
`fable_5_mitigations` / `fable_5_1_prompt_bundle` add sections on top of it.

Writes the JSON capture the parity suite compares against, and the C# table
the App reads. Regenerate rather than hand-editing either.

    python gen-model-catalog.py [path-to-claude.exe]
"""
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.abspath(os.path.join(HERE, "..", "..", "..", ".."))
DEFAULT_EXE = os.path.expanduser("~/.local/bin/claude.exe")

ENTRY = re.compile(r'\{id:"(claude-[a-z0-9.\-]+)",family:"([a-z]+)"')


def extract(exe_path):
    data = open(exe_path, "rb").read()
    anchor = data.find(b'{id:"claude-opus-5",family:"opus"')
    if anchor < 0:
        raise SystemExit("model catalog not found: the anchor entry has moved")
    lo = max(0, anchor - 400_000)
    hi = min(len(data), anchor + 400_000)
    region = data[lo:hi].decode("utf-8", "replace")

    end = region.find("],aliases:{")
    if end < 0:
        raise SystemExit("catalog end not found: the aliases key has moved")
    starts = [m.start() for m in ENTRY.finditer(region) if m.start() < end]
    if not starts:
        raise SystemExit("no catalog entries matched")
    starts.append(end)

    models = {}
    for i in range(len(starts) - 1):
        entry = region[starts[i]:starts[i + 1]]
        model_id = ENTRY.search(entry).group(1)
        caps = re.search(r"capabilities:\[([^\]]*)\]", entry)
        cutoff = re.search(r'knowledge_cutoff:"([^"]*)"', entry)
        if caps is None:
            raise SystemExit(f"{model_id}: no capabilities key inside the entry")
        models[model_id] = {
            "family": ENTRY.search(entry).group(2),
            "knowledge_cutoff": cutoff.group(1) if cutoff else None,
            "capabilities": re.findall(r'"([a-z0-9_]+)"', caps.group(1)),
        }
    return models


def version_of(exe_path):
    """The build the table was read from, for the file's provenance stamp."""
    data = open(exe_path, "rb").read()
    # Anchored on the claude-code feedback channel that follows it: a bare
    # VERSION match also finds an unrelated vendored package's own version.
    m = re.search(
        rb'VERSION:"(2\.\d+\.\d+)",FEEDBACK_CHANNEL:"https://github\.com/anthropics/claude-code',
        data)
    if m is None:
        raise SystemExit("version string not found: the VERSION field has moved")
    return m.group(1).decode()


def emit_csharp(models, version):
    rows = []
    for model_id, entry in models.items():
        caps = ", ".join(f'"{c}"' for c in entry["capabilities"])
        cutoff = "null" if entry["knowledge_cutoff"] is None else f'"{entry["knowledge_cutoff"]}"'
        rows.append(
            f'        ["{model_id}"] = new({cutoff}, [{caps}]),'
        )
    body = "\n".join(rows)
    return f'''// <auto-generated>
// Generated from the reference CLI {version}'s embedded model catalog by
// Captures/Models/gen-model-catalog.py. Regenerate rather than hand-edit.
// </auto-generated>
using System;
using System.Collections.Generic;

namespace JarvisCode.App.Services;

/// <summary>
/// The reference's own model catalog: every model it ships an entry for, its
/// knowledge cutoff and its capability list, verbatim.
/// </summary>
/// <remarks>
/// <para>
/// The capability array is what decides the prompt a model is sent, and it is
/// not derivable from the model's name. <c>lean_prompt</c> selects the lean
/// <c># Harness</c> document over the classic <c># System</c> one;
/// <c>opus_5_prompt_bundle</c>, <c>fable_5_mitigations</c> and
/// <c>fable_5_1_prompt_bundle</c> then add sections on top of it. Two entries
/// show why the name cannot be trusted: <c>claude-sonnet-5</c> is a Claude 5
/// model with no <c>lean_prompt</c>, and <c>claude-mythos-5</c> declares an
/// empty capability list while <c>claude-mythos-5-1</c> beside it carries nine.
/// </para>
/// <para>
/// Measured on CLI {version}. A model this table does not name has no
/// capabilities, which is the reference's own answer for an id its catalog does
/// not carry: the classic prompt, and none of the bundles.
/// </para>
/// </remarks>
internal static class ReferenceModelCatalog
{{
    /// <summary>The build the table was read from, for the parity suite's report.</summary>
    internal const string MeasuredAgainst = "{version}";

    /// <summary>One catalog entry: the cutoff the prompt prints, and the capability list.</summary>
    internal readonly record struct Entry(string? KnowledgeCutoff, IReadOnlyList<string> Capabilities)
    {{
        /// <summary>
        /// Whether the model declares <paramref name="capability"/>. The default
        /// entry — the answer for a model the catalog has no row for — carries no
        /// list at all, and declares nothing.
        /// </summary>
        internal bool Has(string capability)
        {{
            if (Capabilities is null)
            {{
                return false;
            }}

            for (var i = 0; i < Capabilities.Count; i++)
            {{
                if (string.Equals(Capabilities[i], capability, StringComparison.Ordinal))
                {{
                    return true;
                }}
            }}

            return false;
        }}
    }}

    /// <summary>The catalog, keyed by the reference's own model id.</summary>
    internal static readonly IReadOnlyDictionary<string, Entry> Models =
        new Dictionary<string, Entry>(StringComparer.Ordinal)
    {{
{body}
    }};
}}
'''


def main():
    exe = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_EXE
    if not os.path.exists(exe):
        raise SystemExit(f"reference CLI not found at {exe}")
    models = extract(exe)
    version = version_of(exe)

    capture = os.path.join(HERE, f"model-catalog-cli-{version}.json")
    with open(capture, "w", encoding="utf-8", newline="\n") as f:
        json.dump(models, f, indent=1, ensure_ascii=False)
        f.write("\n")

    target = os.path.join(REPO, "src", "JarvisCode.App", "Services", "ReferenceModelCatalog.cs")
    with open(target, "w", encoding="utf-8", newline="\n") as f:
        f.write(emit_csharp(models, version))

    print(f"{len(models)} models from CLI {version}")
    print(f"  {capture}")
    print(f"  {target}")


if __name__ == "__main__":
    main()
